ROOT = Path(__file__).resolve().parents[1]
runs = {s: json.loads((ROOT/f'results/study/{s}/metrics.json').read_text()) for s in ('s2','s3')}
search = json.loads((ROOT/'results/study/development/search.json').read_text())
def pct(x): return '—' if x is None else f'{x*100:.1f}'.replace('.', ',') + '%'
def num(x): return '—' if x is None else f'{x:.1f}'.replace('.', ',')
def para(text): return ('p', text)
def table(rows, widths=None): return ('table', rows, widths)
def sub(text): return ('sub', text)
def model(s, name='SVM'): return runs[s]['models'][name]
def result(s, name='SVM', variant='combined'): return model(s,name)['test'][variant]

class Diagram(Flowable):
    def __init__(self):
        super().__init__()
        self.width = 490
        self.height = 132

    def draw(self):
        canvas = self.canv
        top = ['Электроды', 'Усилитель\nи АЦП', 'Причинный\nфильтр', 'Окно\n100/150 мс', '40 признаков']
        bottom = ['Начало\nдвижения', 'Контроллер\nпривода', 'Связь', 'Проверка\nкоманды', 'LDA / SVM']
        canvas.setStrokeColor(colors.HexColor('#28533a'))
        canvas.setFillColor(colors.HexColor('#202522'))
        canvas.setFont('Body', 8)
        for row, labels in enumerate([top, bottom]):
            y = 82 if row == 0 else 13
            for i, label in enumerate(labels):
                x = i * 100
                canvas.rect(x, y, 88, 39, fill=0)
                parts = label.split('\n')
                for j, line in enumerate(parts):
                    canvas.drawCentredString(x+44, y+23-j*11, line)
                if i < 4:
                    canvas.drawCentredString(x+94, y+18, '→' if row == 0 else '←')
        canvas.drawCentredString(444, 65, '↓')

